'use client';

import { useEffect, useState } from 'react';

const phrases = {
  morning: ['Good Morning', 'Bonjour', 'Namaste'],
  afternoon: ['Good Afternoon', 'Bonjour', 'Namaste'],
  evening: ['Good Evening', 'Bonsoir', 'Ciao'],
  night: ['Good Night', 'Bonne Nuit', 'Buona Notte'],
} as const;

function greetingForHour(hour: number) {
  if (hour < 5 || hour >= 19) return phrases.night;
  if (hour < 12) return phrases.morning;
  if (hour < 17) return phrases.afternoon;
  return phrases.evening;
}

export function AdminGreeting() {
  const [greeting, setGreeting] = useState('Good Morning');
  useEffect(() => {
    const options = greetingForHour(new Date().getHours());
    setGreeting(options[Math.floor(Math.random() * options.length)]);
  }, []);
  return <>{greeting}, admin.</>;
}